import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { FPS, LIGHT, TOTAL } from "./base";
import { Scene1, Scene2, Scene3 } from "./cenas1";
import { Scene4, Scene5, Scene6 } from "./cenas2";

// POR SANTARÉM — "Agora também somos uma agência" (Matheus Publicidade, 13/11/2026). Roteiro do cliente em 6 cenas,
// voz o locutor (src/por-santarem/voz-ps-v1-curta.wav, só o silêncio morto tirado), entra em 0,3 s. Sem áudio aqui:
// a mixagem (tools/audio_ps1.py) entra no ffmpeg depois.
export const PS_FPS = FPS;
export const PS_FRAMES = Math.round(TOTAL * FPS);

export const PorSantarem: React.FC = () => {
  const t = useCurrentFrame() / FPS;
  return (
    <AbsoluteFill style={{ background: LIGHT, overflow: "hidden" }}>
      <Scene1 t={t} />
      <Scene2 t={t} />
      <Scene3 t={t} />
      <Scene4 t={t} />
      <Scene5 t={t} />
      <Scene6 t={t} />
    </AbsoluteFill>
  );
};

import { loadFont } from "@remotion/google-fonts/Rubik";
import React from "react";
import { Easing, interpolate, staticFile } from "remotion";

// POR SANTARÉM (cliente da Matheus Publicidade) — peças comuns.
// Identidade do manual de cores: amarelo #F4B400, vermelho #E10600, preto #1A1A1A, cinza claro #F5F5F5, cinza #6B6B6B;
// apoio verde #4CAF50, azul #0077B6, laranja #FF8C00, roxo #8E44AD. Letra pesada e arredondada como o "POR STM" (Rubik 900).
// Das referências do cliente (reels do vagnerbaumstark): ilustração chapada com cartões e celular, e o mosaico de blocos
// coloridos com ícones; cor que inunda a tela na troca de cena.

export const { fontFamily: FONT } = loadFont("normal", { weights: ["500", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const FPS = 30;
export const VO = 0.3;
export const YEL = "#F4B400";
export const RED = "#E10600";
export const INK = "#1A1A1A";
export const LIGHT = "#F5F5F5";
export const GRAY = "#6B6B6B";
export const GREEN = "#4CAF50";
export const BLUE = "#0077B6";
export const ORANGE = "#FF8C00";
export const PURPLE = "#8E44AD";
export const WHITE = "#FFFFFF";
export const asset = (f: string) => staticFile(`por-santarem/${f}`);

// silêncios tirados da voz (tools/corte_ps1.py): tempo da voz original → tempo do vídeo
const CUTS: [number, number][] = [[3.07, 3.3], [4.89, 5.06], [6.1, 6.45], [8.16, 8.55], [10.03, 10.15], [10.38, 10.69], [14.0, 14.26], [15.57, 15.74], [17.2, 17.37], [19.68, 20.28], [25.03, 25.13], [27.39, 27.54], [34.21, 34.31], [34.54, 34.81], [37.03, 37.19], [38.2, 38.38], [39.51, 39.67], [41.17, 41.34], [43.59, 44.11], [47.31, 47.52], [50.91, 51.16], [53.01, 53.26], [55.19, 55.39], [57.94, 58.16], [59.11, 59.2], [61.22, 61.46], [61.75, 61.94], [63.82, 64.35], [65.78, 65.86], [68.76, 69.43], [70.5, 70.9], [72.58, 72.71], [75.04, 75.68], [76.74, 76.92]];
export const v = (s: number) => {
  let r = s;
  for (const [a, b] of CUTS) r -= s >= b ? b - a : Math.max(0, s - a);
  return r + VO;
};
export const TOTAL = 72;

export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const IN = Easing.bezier(0.7, 0, 0.84, 0);
export const IO = Easing.bezier(0.65, 0, 0.35, 1);
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const ki = (t: number, a: number, d = 0.3) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IO });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const mix = (a: number, b: number, p: number) => a + (b - a) * p;
// mola com pouco passe (3–5%)
export const pop = (t: number, a: number, d = 0.5) => {
  if (t <= a) return 0;
  const x = Math.min(1, (t - a) / d);
  return 1 - Math.exp(-6.5 * x) * Math.cos(x * 5.2) * (1 - x * 0.2);
};
export const bump = (t: number, at: number, amt = 0.05, d = 0.45) => (t >= at && t < at + d ? amt * Math.sin(((t - at) / d) * Math.PI) * (1 - (t - at) / d) : 0);

// ───────── texto por máscara: cada palavra sobe da linha; sai subindo inteira ─────────
type LineProps = { t: number; at: number; text: string; size: number; color?: string; weight?: number; out?: number; gap?: number; stagger?: number; ls?: string; hl?: string };
export const Line: React.FC<LineProps> = ({ t, at, text, size, color = INK, weight = 900, out, gap, stagger = 0.06, ls = "-0.02em", hl }) => {
  if (t < at - 0.05) return null;
  const leave = out !== undefined ? ki(t, out, 0.28) : 0;
  if (leave >= 1) return null;
  const words = text.split(" ");
  return (
    <div style={{ display: "flex", justifyContent: "center", gap: gap ?? size * 0.26, whiteSpace: "nowrap", fontFamily: FONT, fontWeight: weight, fontSize: size, lineHeight: 1.04, letterSpacing: ls, color, overflow: "hidden", padding: `${size * 0.06}px ${size * 0.08}px` }}>
      {words.map((w, i) => {
        const e = k(t, at + i * stagger, 0.42);
        return (
          <span key={i} style={{ display: "inline-block", transform: `translateY(${((1 - e) * 112 - leave * 115).toFixed(2)}%)`, background: hl, padding: hl ? `0 ${size * 0.14}px` : undefined, borderRadius: hl ? size * 0.16 : undefined }}>{w}</span>
        );
      })}
    </div>
  );
};

// ───────── fundo que inunda a partir de um ponto ─────────
// câmera que nunca para: flutua devagar na vertical e inclina de leve (o fundo fica parado, só o conteúdo anda)
export const cam = (t: number) => `translateY(${(Math.sin(t * 0.9) * 14).toFixed(2)}px) rotate(${(Math.sin(t * 0.63 + 1) * 0.35).toFixed(3)}deg)`;
export const Cam: React.FC<{ t: number; children?: React.ReactNode }> = ({ t, children }) => <div style={{ position: "absolute", inset: 0, transform: cam(t) }}>{children}</div>;
export const Flood: React.FC<{ t: number; at: number; x?: number; y?: number; color: string; d?: number; still?: boolean; children?: React.ReactNode }> = ({ t, at, x = 540, y = 960, color, d = 0.6, still, children }) => {
  if (t < at) return null;
  const r = io(t, at, d) * 2300;
  return <div style={{ position: "absolute", inset: 0, background: color, clipPath: r >= 2299 ? undefined : `circle(${r.toFixed(1)}px at ${x}px ${y}px)`, overflow: "hidden" }}>{still ? children : <Cam t={t}>{children}</Cam>}</div>;
};

// ───────── ícones (traço arredondado, 24×24) ─────────
const P: Record<string, React.ReactNode> = {
  music: (<><path d="M9 18V5l12-2v13" /><circle cx="6" cy="18" r="3" /><circle cx="18" cy="16" r="3" /></>),
  cap: (<><path d="M22 10 12 5 2 10l10 5 10-5Z" /><path d="M6 12v5c3 3 9 3 12 0v-5" /><path d="M22 10v6" /></>),
  trophy: (<><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6" /><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18" /><path d="M4 22h16" /><path d="M10 14.7V17c0 .6-.5 1-1 1.2C7.9 18.8 7 20.2 7 22" /><path d="M14 14.7V17c0 .6.5 1 1 1.2 1.1.6 2 2 2 3.8" /><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z" /></>),
  leaf: (<><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.5 19 2c1 2 2 4.2 2 8 0 5.5-4.8 10-10 10Z" /><path d="M2 21c0-3 1.9-5.4 5.1-6C9.5 14.5 12 13 13 12" /></>),
  heart: (<path d="M19 14c1.5-1.5 3-3.2 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.8 0-3 .5-4.5 2-1.5-1.5-2.7-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4 3 5.5l7 7Z" />),
  users: (<><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M22 21v-2a4 4 0 0 0-3-3.9" /><path d="M16 3.1a4 4 0 0 1 0 7.8" /></>),
  camera: (<><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3Z" /><circle cx="12" cy="13" r="3" /></>),
  mega: (<><path d="m3 11 18-5v12L3 14v-3Z" /><path d="M11.6 16.8a3 3 0 1 1-5.8-1.6" /></>),
  target: (<><circle cx="12" cy="12" r="10" /><circle cx="12" cy="12" r="6" /><circle cx="12" cy="12" r="2" /></>),
  route: (<><circle cx="6" cy="19" r="3" /><path d="M9 19h8.5a3.5 3.5 0 0 0 0-7h-11a3.5 3.5 0 0 1 0-7H15" /><circle cx="18" cy="5" r="3" /></>),
  palette: (<><circle cx="13.5" cy="6.5" r="1.2" /><circle cx="17.5" cy="10.5" r="1.2" /><circle cx="8.5" cy="7.5" r="1.2" /><circle cx="6.5" cy="12.5" r="1.2" /><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.9 0 1.6-.7 1.6-1.7 0-.4-.2-.8-.4-1.1-.3-.3-.4-.7-.4-1.1 0-.9.7-1.7 1.7-1.7h2c3.1 0 5.6-2.5 5.6-5.6C22 6 17.5 2 12 2Z" /></>),
  share: (<><circle cx="18" cy="5" r="3" /><circle cx="6" cy="12" r="3" /><circle cx="18" cy="19" r="3" /><path d="m8.6 13.5 6.8 4" /><path d="m15.4 6.5-6.8 4" /></>),
  play: (<><rect x="2" y="4" width="20" height="16" rx="3" /><path d="m10 9 5 3-5 3Z" /></>),
  check: (<><rect x="8" y="2" width="8" height="4" rx="1" /><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2" /><path d="m9 14 2 2 4-4" /></>),
  file: (<><path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z" /><path d="M14 2v4a2 2 0 0 0 2 2h4" /><path d="M16 13H8" /><path d="M16 17H8" /><path d="M10 9H8" /></>),
  eye: (<><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" /><circle cx="12" cy="12" r="3" /></>),
  chart: (<><path d="M22 7 13.5 15.5 8.5 10.5 2 17" /><path d="M16 7h6v6" /></>),
  chat: (<path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z" />),
  send: (<><path d="m22 2-7 20-4-9-9-4Z" /><path d="M22 2 11 13" /></>),
  user: (<><circle cx="12" cy="8" r="4" /><path d="M4 21v-1a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v1" /></>),
  book: (<><path d="M2 4h6a4 4 0 0 1 4 4v13a3 3 0 0 0-3-3H2Z" /><path d="M22 4h-6a4 4 0 0 0-4 4v13a3 3 0 0 1 3-3h7Z" /></>),
};
export type IconName = keyof typeof P;
export const Icon: React.FC<{ name: IconName; size: number; color?: string; stroke?: number; draw?: number }> = ({ name, size, color = WHITE, stroke = 2.2, draw = 1 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" style={{ display: "block", overflow: "visible" }}>
    <g pathLength={1} strokeDasharray={draw < 1 ? "1" : undefined} style={draw < 1 ? { strokeDashoffset: 1 - draw } : undefined}>{P[name]}</g>
  </svg>
);

// bloco colorido com ícone (o "ladrilho" do mosaico)
export const Tile: React.FC<{ s: number; c: string; icon?: IconName; ic?: string; r?: number; style?: React.CSSProperties }> = ({ s, c, icon, ic = WHITE, r, style }) => (
  <div style={{ width: s, height: s, borderRadius: r ?? s * 0.2, background: c, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, ...style }}>
    {icon ? <Icon name={icon} size={s * 0.5} color={ic} stroke={2.4} /> : null}
  </div>
);

// o símbolo (raios amarelos) revelado em partes: primeiro a barra, depois os raios saem dela para a esquerda
export const Symbol: React.FC<{ t: number; at: number; w: number }> = ({ t, at, w }) => {
  const h = (w * 609) / 401;
  const bar = io(t, at, 0.35);
  const rays = k(t, at + 0.22, 0.5);
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      {/* barra vertical: x 305–400 da imagem */}
      <img src={asset("logo-simbolo.png")} style={{ position: "absolute", inset: 0, width: w, height: h, clipPath: `inset(${((1 - bar) * 100).toFixed(2)}% 0 0 ${(305 / 401) * 100}%)` }} />
      <img src={asset("logo-simbolo.png")} style={{ position: "absolute", inset: 0, width: w, height: h, clipPath: `inset(0 ${(100 - (305 / 401) * 100).toFixed(2)}% 0 ${((1 - rays) * (305 / 401) * 100).toFixed(2)}%)` }} />
    </div>
  );
};

import React from "react";
import { AbsoluteFill, Img } from "remotion";
import { asset, BLUE, bump, Cam, Flood, FONT, GREEN, Icon, IconName, INK, io, k, ki, LIGHT, lin, Line, mix, ORANGE, pop, PURPLE, RED, Symbol, Tile, v, WHITE, YEL, GRAY } from "./base";

// largura útil: coluna central de 840 px; tamanho do texto encolhe para caber
export const fit = (txt: string, base: number, w = 800) => Math.min(base, Math.floor(w / (txt.length * 0.7)));

// ───────── o mosaico (abertura e "muitas outras iniciativas") ─────────
const MOS: [string, IconName | null, number][] = [
  [YEL, "music", 0], [RED, null, 1], [BLUE, "cap", 0], [GREEN, "leaf", 0], ["#E2E2E2", null, 2], [ORANGE, "trophy", 0],
  [PURPLE, "users", 0], [INK, "camera", 0], [RED, "heart", 0], [ORANGE, null, 1], [YEL, "book", 0], [BLUE, null, 2],
  [GREEN, "mega", 0], [PURPLE, null, 1], [RED, "chat", 0],
];
const ORDER = [7, 1, 12, 4, 9, 0, 14, 5, 10, 2, 13, 8, 3, 11, 6];
// ordem de saída: do mais perto do miolo (onde entra o texto) para as bordas
const LEAVE_ORDER = MOS.map((_, i) => i).sort((a, b) => Math.hypot((a % 3) - 1, Math.floor(a / 3) - 1.5) - Math.hypot((b % 3) - 1, Math.floor(b / 3) - 1.5));
export const Mosaic: React.FC<{ t: number; at: number; leave?: number }> = ({ t, at, leave }) => {
  const S = 300, G = 24, L = (1080 - (3 * S + 2 * G)) / 2, T = (1920 - (5 * S + 4 * G)) / 2;
  const cam = mix(1.28, 1.0, io(t, at, 1.7)) + lin(t, at + 1.7, at + 9) * 0.04;
  return (
    <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)}) rotate(${mix(-4, 0, io(t, at, 1.7)).toFixed(2)}deg)` }}>
      {MOS.map(([c, ic, shape], i) => {
        const col = i % 3, row = Math.floor(i / 3);
        const e = pop(t, at + ORDER.indexOf(i) * 0.06, 0.55);
        const x = L + col * (S + G), y = T + row * (S + G);
        // saída (v6): cada ladrilho encolhe no próprio lugar, do meio para fora, e some antes do texto seguinte
        const rank = LEAVE_ORDER.indexOf(i);
        const go = leave !== undefined ? ki(t, leave + rank * 0.012, 0.24) : 0;
        const r = shape === 1 ? S / 2 : shape === 2 ? `${S / 2}px ${S / 2}px 40px 40px` : 56;
        return (
          <div key={i} style={{ position: "absolute", left: x, top: y, transform: `scale(${(e * (1 - go)).toFixed(3)}) rotate(${((1 - e) * (i % 2 ? 24 : -24) + go * (i % 2 ? 35 : -35)).toFixed(2)}deg)` }}>
            <div style={{ width: S, height: S, borderRadius: r, background: c, display: "flex", alignItems: "center", justifyContent: "center", boxSizing: "border-box" }}>
              {ic ? <Icon name={ic} size={S * 0.46} color={c === YEL || c === LIGHT ? INK : WHITE} stroke={2.3} /> : null}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ───────── CENA 1: mosaico de projetos → "precisa de planejamento, estratégia e… comunicação" ─────────
export const Scene1: React.FC<{ t: number }> = ({ t }) => {
  if (t > v(8.62) + 0.7) return null;
  const card = pop(t, 0.12, 0.55) * (1 - ki(t, v(3.08), 0.26));
  const row = (at: number, c: string, ic: IconName, word: string, y: number) => {
    const e = pop(t, at - 0.06, 0.5);
    return (
      <div style={{ position: "absolute", left: 120, right: 120, top: y + lift, display: "flex", alignItems: "center", justifyContent: "center", gap: 28 }}>
        <div style={{ transform: `scale(${e.toFixed(3)}) rotate(${((1 - e) * -40).toFixed(1)}deg)` }}><Tile s={140} c={c} icon={ic} /></div>
        <Line t={t} at={at} text={word} size={fit(word, 88, 640)} color={INK} />
      </div>
    );
  };
  const mega = pop(t, v(6.77) - 0.05, 0.55);
  const lift = 220 * (1 - io(t, v(6.3), 0.5));
  return (
    <AbsoluteFill style={{ background: LIGHT }}>
      <Cam t={t}>
      {t < v(3.59) + 0.6 ? <Mosaic t={t} at={0} leave={v(3.08)} /> : null}
      {/* cartão preto no meio do mosaico */}
      {card > 0.001 ? (
        <div style={{ position: "absolute", left: 120, top: 640, width: 840, height: 640, borderRadius: 56, background: INK, transform: `scale(${card.toFixed(3)})`, boxShadow: "0 30px 60px rgba(0,0,0,0.25)" }} />
      ) : null}
      <div style={{ position: "absolute", left: 120, right: 120, top: 640, height: 640, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6 }}>
        {t < v(1.0) + 0.3 ? (
          <>
            <Line t={t} at={v(0.11) - 0.06} text="TODO GRANDE" size={92} color={WHITE} out={v(1.0)} />
            <Line t={t} at={v(0.61) - 0.06} text="PROJETO" size={150} color={YEL} out={v(1.0)} />
          </>
        ) : (
          <>
            <Line t={t} at={v(1.09) - 0.05} text="precisa de mais do que" size={58} weight={700} color={WHITE} stagger={0.05} out={v(3.06)} ls="-0.01em" />
            <Line t={t} at={v(2.03) - 0.06} text="UMA BOA" size={112} color={YEL} out={v(3.06)} />
            <Line t={t} at={v(2.35) - 0.06} text="EXECUÇÃO." size={112} color={YEL} out={v(3.06)} />
          </>
        )}
      </div>
      {/* a lista: planejamento, estratégia e, principalmente… */}
      <div style={{ position: "absolute", left: 0, right: 0, top: 380 + lift }}>
        <Line t={t} at={v(3.59) - 0.05} text="PRECISA DE" size={64} weight={800} color={GRAY} />
      </div>
      {row(v(4.03), RED, "target", "PLANEJAMENTO", 520)}
      {row(v(5.19), BLUE, "route", "ESTRATÉGIA", 700)}
      <div style={{ position: "absolute", left: 0, right: 0, top: 930 }}>
        <Line t={t} at={v(6.55) - 0.05} text="e, principalmente," size={66} weight={700} color={GRAY} ls="-0.01em" />
      </div>
      {mega > 0.001 ? (
        <div style={{ position: "absolute", left: 540 - 190, top: 1110, transform: `scale(${(mega + bump(t, v(7.6), 0.06)).toFixed(3)}) rotate(${((1 - mega) * 30 + Math.sin(t * 9) * 2.5 * lin(t, v(7.0), v(7.3))).toFixed(2)}deg)` }}>
          <Tile s={380} c={RED} icon="mega" r={90} />
          {/* ondas de som saindo do megafone */}
          {[0, 1, 2].map((i) => {
            const ph = ((t - v(7.0) - i * 0.33) % 1 + 1) % 1;
            return t > v(7.0) ? <div key={i} style={{ position: "absolute", left: 190 - 190, top: 0, width: 380, height: 380, borderRadius: 90, border: `8px solid ${RED}`, opacity: (1 - ph) * 0.5, transform: `scale(${(1 + ph * 0.45).toFixed(3)})` }} /> : null;
          })}
        </div>
      ) : null}
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── CENA 2: vermelho; "COMUNICAÇÃO!", o celular só no "EFICIENTE" e depois uma cena gráfica por ideia ─────────
// (v4: "muito tempo só essa imagem e esse modelo" → cada frase ganha fundo, cor e desenho próprios)
type Pal = { big: string; big2: string; small: string };
type Block = { at: number; out: number; lines: [string, number, "big" | "big2" | "small"][]; bg: string; pal: Pal; fx: number; fy: number };
const ONRED: Pal = { big: YEL, big2: WHITE, small: WHITE };
const BLOCKS: Block[] = [
  { at: 10.81, out: 12.1, lines: [["uma comunicação", 10.81, "small"], ["EFICIENTE", 11.55, "big"]], bg: RED, pal: ONRED, fx: 540, fy: 1300 },
  { at: 12.2, out: 14.35, lines: [["VISIBILIDADE", 12.34, "big"], ["às iniciativas", 13.06, "small"]], bg: INK, pal: ONRED, fx: 540, fy: 0 },
  { at: 14.42, out: 15.85, lines: [["APROXIMA", 14.42, "big"], ["PESSOAS", 14.86, "big2"]], bg: BLUE, pal: ONRED, fx: 1080, fy: 700 },
  { at: 15.92, out: 17.45, lines: [["FORTALECE", 15.92, "big"], ["AÇÕES", 16.52, "big2"]], bg: YEL, pal: { big: RED, big2: INK, small: INK }, fx: 540, fy: 1920 },
